Before writing native code: [`battery_plus`](https://pub.dev/packages/battery_plus) already covers battery level, charging-state stream, and power-save mode on Android and iOS. If it meets your needs, use it. Custom code is worth it only for a concrete gap, such as one combined snapshot or event, temperature or health, a capability report, or no third-party dependency. If your project already uses `battery_plus`, tell me what it fails to do and I'll close only that gap.

The rest assumes you need a controlled native contract.

## Boundary choice

- **Pigeon** for the commands, since several methods benefit from typed generated code.
- **Pigeon `@EventChannelApi`** for the stream. This needs a recent Pigeon with event-channel support and Kotlin/Swift output. If your Pigeon version lacks it, use a plain `EventChannel` with the same payload.
- **App-local integration**, not a published plugin. If this should become a reusable package, `flutter-package-development` should drive the API and federation design.

## 1. Contract: `pigeons/battery.dart`

```dart
import 'package:pigeon/pigeon.dart';

@ConfigurePigeon(PigeonOptions(
  dartOut: 'lib/src/battery/battery_api.g.dart',
  kotlinOut: 'android/app/src/main/kotlin/com/example/app/battery/BatteryApi.g.kt',
  kotlinOptions: KotlinOptions(package: 'com.example.app.battery'),
  swiftOut: 'ios/Runner/Battery/BatteryApi.g.swift',
))

enum ChargeStateMessage { unknown, unplugged, charging, full }

class BatterySnapshotMessage {
  BatterySnapshotMessage({required this.level, required this.state, required this.powerSave});
  int? level;            // 0..100, null when unknown (e.g. iOS simulator)
  ChargeStateMessage state;
  bool powerSave;
}

class BatteryCapabilitiesMessage {
  BatteryCapabilitiesMessage({required this.levelAvailable, required this.powerSaveAvailable});
  bool levelAvailable;
  bool powerSaveAvailable;
}

@HostApi()
abstract class BatteryHostApi {
  BatterySnapshotMessage getSnapshot();
  bool isPowerSaveEnabled();
  BatteryCapabilitiesMessage getCapabilities();
}

@EventChannelApi()
abstract class BatteryEventApi {
  BatterySnapshotMessage batteryUpdates();
}
```

Generate with `dart run pigeon --input pigeons/battery.dart`. The `*Message` types are wire types only. The app uses its own domain model, defined in step 4.

## 2. Android: `BatteryBridge.kt`

```kotlin
package com.example.app.battery

import android.content.*
import android.os.BatteryManager
import android.os.PowerManager
import androidx.core.content.ContextCompat
import io.flutter.embedding.engine.plugins.FlutterPlugin

class BatteryBridge : FlutterPlugin, BatteryHostApi {
  private lateinit var context: Context
  private var streamHandler: UpdatesHandler? = null

  override fun onAttachedToEngine(binding: FlutterPlugin.FlutterPluginBinding) {
    context = binding.applicationContext
    BatteryHostApi.setUp(binding.binaryMessenger, this)
    streamHandler = UpdatesHandler(context, ::snapshot).also {
      BatteryUpdatesStreamHandler.register(binding.binaryMessenger, it)
    }
  }

  override fun onDetachedFromEngine(binding: FlutterPlugin.FlutterPluginBinding) {
    BatteryHostApi.setUp(binding.binaryMessenger, null)
    streamHandler?.stop()   // never leak the receiver past the engine
    streamHandler = null
  }

  override fun getSnapshot() = snapshot(null)
  override fun isPowerSaveEnabled() = powerManager().isPowerSaveMode
  override fun getCapabilities() =
    BatteryCapabilitiesMessage(levelAvailable = true, powerSaveAvailable = true)

  private fun powerManager() = context.getSystemService(Context.POWER_SERVICE) as PowerManager

  private fun snapshot(intent: Intent?): BatterySnapshotMessage {
    val battery = intent ?: context.registerReceiver(null, IntentFilter(Intent.ACTION_BATTERY_CHANGED))
      ?: throw FlutterError("unavailable", "Battery status broadcast unavailable", null)
    val raw = battery.getIntExtra(BatteryManager.EXTRA_LEVEL, -1)
    val scale = battery.getIntExtra(BatteryManager.EXTRA_SCALE, -1)
    val level = if (raw >= 0 && scale > 0) (raw * 100 / scale).coerceIn(0, 100) else null
    val state = when (battery.getIntExtra(BatteryManager.EXTRA_STATUS, -1)) {
      BatteryManager.BATTERY_STATUS_CHARGING -> ChargeStateMessage.CHARGING
      BatteryManager.BATTERY_STATUS_FULL -> ChargeStateMessage.FULL
      BatteryManager.BATTERY_STATUS_DISCHARGING,
      BatteryManager.BATTERY_STATUS_NOT_CHARGING -> ChargeStateMessage.UNPLUGGED
      else -> ChargeStateMessage.UNKNOWN
    }
    return BatterySnapshotMessage(level, state, powerManager().isPowerSaveMode)
  }

  private class UpdatesHandler(
    private val context: Context,
    private val snapshot: (Intent?) -> BatterySnapshotMessage,
  ) : BatteryUpdatesStreamHandler() {
    private var receiver: BroadcastReceiver? = null

    override fun onListen(p0: Any?, sink: PigeonEventSink<BatterySnapshotMessage>) {
      stop()
      receiver = object : BroadcastReceiver() {
        override fun onReceive(c: Context, i: Intent) {
          val src = if (i.action == Intent.ACTION_BATTERY_CHANGED) i else null
          try { sink.success(snapshot(src)) }
          catch (e: FlutterError) { sink.error(e.code, e.message, e.details) }
        }
      }
      val filter = IntentFilter().apply {
        addAction(Intent.ACTION_BATTERY_CHANGED)               // sticky: emits current value immediately
        addAction(PowerManager.ACTION_POWER_SAVE_MODE_CHANGED)
      }
      ContextCompat.registerReceiver(context, receiver, filter, ContextCompat.RECEIVER_NOT_EXPORTED)
    }

    override fun onCancel(p0: Any?) = stop()

    fun stop() { receiver?.let { context.unregisterReceiver(it) }; receiver = null }
  }
}
```

Register it in `MainActivity.configureFlutterEngine` with `flutterEngine.plugins.add(BatteryBridge())`. Each engine gets its own instance, so multiple engines are safe. No permission is required.

## 3. iOS: `BatteryBridge.swift`

```swift
import Flutter
import UIKit

final class BatteryBridge: NSObject, BatteryHostApi {
  private let updates = UpdatesHandler()

  static func register(with registrar: FlutterPluginRegistrar) {
    let bridge = BatteryBridge()
    BatteryHostApiSetup.setUp(binaryMessenger: registrar.messenger(), api: bridge)
    BatteryUpdatesStreamHandler.register(with: registrar.messenger(), streamHandler: bridge.updates)
  }

  func getSnapshot() throws -> BatterySnapshotMessage { Self.snapshot() }
  func isPowerSaveEnabled() throws -> Bool { ProcessInfo.processInfo.isLowPowerModeEnabled }
  func getCapabilities() throws -> BatteryCapabilitiesMessage {
    BatteryCapabilitiesMessage(levelAvailable: !Self.isSimulator, powerSaveAvailable: true)
  }

  static var isSimulator: Bool {
    #if targetEnvironment(simulator)
    true
    #else
    false
    #endif
  }

  static func snapshot() -> BatterySnapshotMessage {
    let device = UIDevice.current
    device.isBatteryMonitoringEnabled = true
    let raw = device.batteryLevel                     // -1 when unknown
    let level: Int64? = raw < 0 ? nil : Int64(min(max(raw * 100, 0), 100).rounded())
    let state: ChargeStateMessage
    switch device.batteryState {
    case .charging: state = .charging
    case .full: state = .full
    case .unplugged: state = .unplugged
    default: state = .unknown
    }
    return BatterySnapshotMessage(level: level, state: state,
                                  powerSave: ProcessInfo.processInfo.isLowPowerModeEnabled)
  }

  final class UpdatesHandler: BatteryUpdatesStreamHandler {
    private var observers: [NSObjectProtocol] = []

    override func onListen(withArguments arguments: Any?, sink: PigeonEventSink<BatterySnapshotMessage>) {
      stop()
      UIDevice.current.isBatteryMonitoringEnabled = true
      let names: [Notification.Name] = [
        UIDevice.batteryLevelDidChangeNotification,
        UIDevice.batteryStateDidChangeNotification,
        .NSProcessInfoPowerStateDidChange,          // posted off the main thread
      ]
      observers = names.map { name in
        NotificationCenter.default.addObserver(forName: name, object: nil, queue: .main) { _ in
          sink.success(BatteryBridge.snapshot())
        }
      }
      sink.success(BatteryBridge.snapshot())          // match Android's immediate first value
    }

    override func onCancel(withArguments arguments: Any?) { stop() }

    func stop() {
      observers.forEach(NotificationCenter.default.removeObserver)
      observers.removeAll()
    }
  }
}
```

Register it in `AppDelegate`:

```swift
BatteryBridge.register(with: self.registrar(forPlugin: "BatteryBridge")!)
```

If the app has migrated to UIScene, register in `didInitializeImplicitFlutterEngine` instead. Battery monitoring stays enabled after the stream is cancelled because other code may rely on it. iOS also delivers no updates while the app is suspended, so treat the stream as foreground-only on both platforms.

## 4. Dart adapter: `lib/src/battery/battery_service.dart`

```dart
import 'dart:async';
import 'dart:io' show Platform;
import 'package:flutter/foundation.dart' show kIsWeb;
import 'package:flutter/services.dart';
import 'battery_api.g.dart';

enum ChargeState { unknown, unplugged, charging, full }

class BatteryStatus {
  const BatteryStatus({required this.level, required this.state, required this.powerSave});
  final int? level;
  final ChargeState state;
  final bool powerSave;
}

class BatteryException implements Exception {
  BatteryException(this.code, this.message);
  final String code;
  final String message;
  @override
  String toString() => 'BatteryException($code): $message';
}

class BatteryService {
  BatteryService({BatteryHostApi? api, Stream<BatterySnapshotMessage> Function()? updates})
      : _api = api ?? BatteryHostApi(),
        _updates = updates ?? batteryUpdates;

  final BatteryHostApi _api;
  final Stream<BatterySnapshotMessage> Function() _updates;

  static bool get isSupported => !kIsWeb && (Platform.isAndroid || Platform.isIOS);

  Future<BatteryStatus> snapshot() => _guard(() async => _map(await _api.getSnapshot()));
  Future<bool> isPowerSaveEnabled() => _guard(_api.isPowerSaveEnabled);
  Future<BatteryCapabilitiesMessage> capabilities() => _guard(_api.getCapabilities);

  Stream<BatteryStatus> watch() {
    _requireSupported();
    return _updates().map(_map).handleError(
      (Object e) => throw _toDomain(e),
      test: (e) => e is PlatformException,
    );
  }

  Future<T> _guard<T>(Future<T> Function() call) async {
    _requireSupported();
    try {
      return await call();
    } on PlatformException catch (e) {
      throw _toDomain(e);
    }
  }

  void _requireSupported() {
    if (!isSupported) {
      throw UnsupportedError('Battery monitoring is only implemented on Android and iOS.');
    }
  }

  BatteryException _toDomain(Object e) => e is PlatformException
      ? BatteryException(e.code, e.message ?? 'Battery platform call failed')
      : BatteryException('unknown', '$e');

  BatteryStatus _map(BatterySnapshotMessage m) {
    final level = m.level;
    if (level != null && (level < 0 || level > 100)) {
      throw BatteryException('invalid_level', 'Native layer reported level $level');
    }
    return BatteryStatus(
      level: level,
      state: ChargeState.values[m.state.index],
      powerSave: m.powerSave,
    );
  }
}
```

The adapter validates values at the boundary, maps platform errors to `BatteryException`, and fails with a clear `UnsupportedError` on other platforms instead of a late `MissingPluginException`. Callers who need to avoid the throw can check `isSupported` first.

## Verification

- **Dart unit tests:** inject a fake `BatteryHostApi` and a fake update stream. Cover the mapping, out-of-range rejection, `PlatformException` to `BatteryException` conversion, and unsupported-platform behavior.
- **Android (physical device + emulator):** confirm the first event arrives immediately. Drive changes with `adb shell dumpsys battery set level 42`, `dumpsys battery unplug`, and `settings put global low_power 1`. Cancel the subscription and check that the receiver is unregistered. Detach and reattach the engine (rotate, or background then restore) and confirm the stream resumes.
- **iOS (physical device):** the simulator reports level `nil` and state `unknown`, which `getCapabilities` exposes. Toggle Low Power Mode, plug and unplug, and confirm events arrive on resume after backgrounding.
- **Integration test:** run on both platforms to subscribe, cancel, and resubscribe without leaks or duplicate events.
